<?php
require dirname(__DIR__).'/lib/bootstrap.php';require_admin();verify_csrf();
if(($_FILES['csv']['error']??1)!==UPLOAD_ERR_OK)exit('Falha no arquivo.');$h=fopen($_FILES['csv']['tmp_name'],'r');$header=fgetcsv($h,0,';');$count=0;
$sql='INSERT INTO kids_products (sku,name,presentation,category,age_group,price,old_price,image) VALUES (?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE name=VALUES(name),presentation=VALUES(presentation),category=VALUES(category),age_group=VALUES(age_group),price=VALUES(price),old_price=VALUES(old_price),image=COALESCE(VALUES(image),image),active=1';$stmt=$pdo->prepare($sql);
while(($r=fgetcsv($h,0,';'))!==false){if(count($r)<6)continue;[$sku,$name,$presentation,$category,$age,$price]=$r;$old=$r[6]??null;$sku=strtoupper(trim($sku));$image=null;foreach(['webp','jpg','png'] as $ext){$candidate='uploads/kids_products/'.$sku.'.'.$ext;if(is_file(dirname(__DIR__).'/'.$candidate)){$image=$candidate;break;}}$decimal=fn($v)=>(float)str_replace(',','.',preg_replace('/[^0-9,.-]/','',(string)$v));$stmt->execute([$sku,trim($name),trim($presentation),trim($category),in_array($age,['all','0-6','6-12','1-3','3+'],true)?$age:'all',$decimal($price),$old!==''?$decimal($old):null,$image]);$count++;}fclose($h);$_SESSION['flash']="$count produto(s) importado(s). As fotos com SKU igual foram vinculadas automaticamente.";header('Location: '.base_url('admin/index.php'));

